def get_logo_dir() -> Path:
    return LOGO_DIR


def set_logo_dir(path: str | Path) -> Path:
    global LOGO_DIR
    LOGO_DIR = Path(path).expanduser()
    LOGO_DIR.mkdir(parents=True, exist_ok=True)
    return LOGO_DIR


def _unique_dest_path(dst_dir: Path, name: str) -> Path:
    dst = dst_dir / name
    if not dst.exists():
        return dst
    stem = dst.stem
    suffix = dst.suffix
    for i in range(1, 1000):
        cand = dst_dir / f"{stem}_{i}{suffix}"
        if not cand.exists():
            return cand
    raise FileExistsError(f"保存先のファイル名が多すぎます: {name}")


def _set_windows_app_id():
    """Windows のタスクバー/Alt+Tab 用にアプリIDを明示する。"""
    if sys.platform != "win32":
        return
    try:
        import ctypes
        app_id = f"{APP_AUTHOR}.{APP_NAME}.{APP_VERSION}"
        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(app_id)
    except Exception:
        pass


def _build_app_icon() -> QIcon:
    """埋め込み ICO からアプリ用アイコンを組み立てる。"""
    try:
        import base64 as _b64
        import tempfile as _tf, os as _os
        _ico_bytes = _b64.b64decode(_APP_ICON_B64)
        _fd, _tmp_path = _tf.mkstemp(suffix=".ico")
        try:
            _os.write(_fd, _ico_bytes)
            _os.close(_fd)
            return QIcon(_tmp_path)
        finally:
            try:
                _os.unlink(_tmp_path)
            except Exception:
                pass
    except Exception:
        return QIcon()

