def get_default_image_folder() -> str:
    """Return a reasonable startup folder without leaking local machine paths."""
    env_path = os.environ.get(DEFAULT_IMAGE_ROOT_ENV, "").strip()
    if env_path and os.path.isdir(env_path):
        return env_path

    candidates = [
        Path.home() / "Pictures",
        Path.home() / "Downloads",
        Path.home(),
    ]
    for candidate in candidates:
        if candidate.is_dir():
            return str(candidate)
    return str(Path.home())


def get_civitai_api_key() -> str:
    """Load the optional API key from the environment for public-safe distribution."""
    return os.environ.get(CIVITAI_API_KEY_ENV, "").strip()


def normalize_right_vsplit_sizes(saved_sizes) -> list[int]:
    """Prevent the right-side vertical splitter from restoring nearly collapsed panes."""
    fallback = [240, 360]
    if not (isinstance(saved_sizes, list) and len(saved_sizes) == 2):
        return fallback
    try:
        top = max(int(saved_sizes[0]), RIGHT_PANEL_MIN_PREVIEW_HEIGHT)
        bottom = max(int(saved_sizes[1]), RIGHT_PANEL_MIN_META_HEIGHT)
        return [top, bottom]
    except Exception:
        return fallback


def _sanitize_logo_stem(text: str) -> str:
    """ロゴ保存用のファイル名を安全な形に整える。"""
    text = re.sub(r"[^\w\-]+", "_", (text or "").strip(), flags=re.UNICODE)
    text = text.strip("._-")
    return text or "logo"


def import_logo_as_webp(source_path: str, stem_hint: str = "") -> str:
    """登録用のロゴ画像を `webp` に変換して `LOGO_DIR` に保存する。

    既に `LOGO_DIR` 配下の `.webp` であれば、そのまま返す。
    """
    if not source_path:
        raise FileNotFoundError("ロゴ画像が指定されていません")
    src = Path(source_path)
    if not src.is_file():
        raise FileNotFoundError(f"ロゴ画像が見つかりません: {source_path}")
    logo_dir = get_logo_dir()

    try:
        resolved = src.resolve()
        if resolved.suffix.lower() == ".webp" and logo_dir in resolved.parents:
            return str(resolved)
    except Exception:
        pass

    logo_dir.mkdir(parents=True, exist_ok=True)
    stem = _sanitize_logo_stem(stem_hint or src.stem or "logo")
    try:
        stat = src.stat()
        unique = hashlib.sha1(
            f"{src.resolve()}|{stat.st_mtime_ns}|{stat.st_size}".encode("utf-8", "ignore")
        ).hexdigest()[:10]
    except Exception:
        unique = hashlib.sha1(f"{source_path}|{datetime.now().timestamp()}".encode("utf-8", "ignore")).hexdigest()[:10]

    dst = logo_dir / f"{stem}_{unique}.webp"
    with Image.open(src) as im:
        if im.mode not in ("RGBA", "RGB", "P"):
            im = im.convert("RGBA")
        else:
            im = im.convert("RGBA")
        im.save(dst, format="WEBP", lossless=True, method=6)
    return str(dst)


def clamp_splitter_sizes(total: int, sizes: list[int], minimums: list[int], fallback: list[int] | None = None) -> list[int]:
    """Clamp splitter sizes so they stay usable inside the current total width/height.

    Qt accepts oversized restore values, but absolute pixel sizes can make the
    window feel "stuck" when the saved pane widths are larger than the current
    available space.  This helper keeps the intent of the saved proportions while
    still letting the window shrink normally.
    """
    if fallback is None:
        fallback = list(minimums)
    if not (isinstance(sizes, list) and len(sizes) == len(minimums)):
        return list(fallback)
    try:
        total = max(int(total), 0)
        mins = [max(int(v), 0) for v in minimums]
        vals = [max(int(v), 0) for v in sizes]
    except Exception:
        return list(fallback)

    min_total = sum(mins)
    if total <= 0:
        return list(fallback)
    if total <= min_total:
        # Not enough room to honor the preferred sizes; keep the minimums.
        return list(mins)

    extra = total - min_total
    base = sum(vals)
    if base <= 0:
        # Fall back to the minimums and share remaining space by weight.
        weights = [max(v, 1) for v in mins]
        weight_sum = sum(weights) or len(weights)
        result = mins[:]
        used = 0
        for i, w in enumerate(weights):
            add = extra * w // weight_sum
            result[i] += add
            used += add
        if result:
            result[-1] += extra - used
        return result

    result = mins[:]
    used = 0
    for i, v in enumerate(vals):
        add = extra * v // base
        result[i] += add
        used += add
    if result:
        result[-1] += extra - used
    return result


class _ToolbarHost(QWidget):
    """Toolbar content container with a deliberately tiny width hint.

    The visible controls still render inside it, but Qt will no longer treat the
    toolbar as if it needs to be as wide as the entire control set.
    """

    def sizeHint(self):
        return QSize(0, 72)

    def minimumSizeHint(self):
        return QSize(0, 72)


class _FlexiblePane(QWidget):
    """Generic container that should not impose a width hint on its parent."""

    def sizeHint(self):
        return QSize(0, 0)

    def minimumSizeHint(self):
        return QSize(0, 0)

