# ══════════════════════════════════════════════════════════════════════════════
#  ユーティリティ
# ══════════════════════════════════════════════════════════════════════════════
def _normalize_path(path: str) -> str:
    """パスを正規化する。
    スラッシュをOSのセパレータに統一し、Windows拡張パスのプレフィックスを除去する。
    MAX_PATH(260文字超)のWindowsパスにはUNCプレフィックスを付与する。
    例外が発生した場合は元のパスをそのまま返す（クラッシュ防止）。
    """
    if not path:
        return path
    try:
        p = path.replace("/", os.sep)
        sep2 = os.sep * 2
        unc_ext = sep2 + "?" + os.sep + "UNC" + os.sep
        ext_pfx = sep2 + "?" + os.sep
        if p.startswith(unc_ext):
            p = sep2 + p[len(unc_ext):]
        elif p.startswith(ext_pfx):
            p = p[len(ext_pfx):]
        if sys.platform == "win32":
            # os.path.abspath で絶対パスに正規化してから長さを判定する。
            # UNCパス (\\server\share) や相対パスも正確に計測できる。
            try:
                p_abs = os.path.abspath(p)
            except Exception:
                p_abs = p
            if len(p_abs) > 259 and not p_abs.startswith(sep2 + "?"):
                if p_abs.startswith(sep2):
                    p = sep2 + "?" + os.sep + "UNC" + os.sep + p_abs[2:]
                elif len(p_abs) >= 2 and p_abs[1] == ":":
                    p = sep2 + "?" + os.sep + p_abs
                else:
                    p = p_abs
            else:
                p = p_abs
        return p
    except Exception:
        return path

