# ── PNG / 画像メタ ──────────────────────────────────────────────────────────
_RE_NORM      = re.compile(r"[\s_]+")
_RE_SPLIT_CSV = re.compile(r",\s*")
_RE_QUERY_SPLIT = re.compile(r"[,、\n]+")
_RE_NEG       = re.compile(r"\nNegative prompt:", re.IGNORECASE)
_RE_STEPS     = re.compile(r"\nSteps:", re.IGNORECASE)
_RE_LORA      = re.compile(r"<lora:([^:>]+)(?::([^>]*))?>" )
_RE_LORA_FULL = re.compile(r"^<lora:([^:>]+)(?::([^>]*))?>$", re.IGNORECASE)
_RE_PARAM     = re.compile(r"(?:^|,\s*)(\w[\w\s]*):\s*([^,\n]+)", re.MULTILINE)

def norm_tag(t: str) -> str:
    return _RE_NORM.sub(" ", t.strip().lower())

def _split_prompt_tokens(text: str) -> list[str]:
    """プロンプト文字列をカンマ区切りベースで分割しつつ、LoRAタグは単独トークン扱いにする。"""
    if not text or not text.strip():
        return []
    tokens: list[str] = []
    pos = 0
    for m in _RE_LORA.finditer(text):
        before = text[pos:m.start()]
        if before:
            tokens.extend(t.strip() for t in _RE_SPLIT_CSV.split(before) if t.strip())
        lora = m.group(0).strip()
        if lora:
            tokens.append(lora)
        pos = m.end()
    tail = text[pos:]
    if tail:
        tokens.extend(t.strip() for t in _RE_SPLIT_CSV.split(tail) if t.strip())
    return tokens

def _normalize_lora_token(token: str) -> str:
    """LoRAタグを重複判定用に正規化する。強度はあれば保持、なければ省略する。"""
    m = _RE_LORA_FULL.match(token.strip())
    if not m:
        return token.strip()
    name = " ".join(norm_tag(m.group(1)).split())
    strength = (m.group(2) or "").strip()
    if strength:
        return f"<lora:{name}:{strength}>"
    return f"<lora:{name}>"

def tag_list(text: str) -> list:
    if not text or not text.strip(): return []
    lora_names = _RE_LORA.findall(text)
    text2 = _RE_LORA.sub(",", text)
    tags = [t.strip() for t in _RE_SPLIT_CSV.split(text2)
            if t.strip() and not t.strip().startswith("<")]
    tags += [n.strip() for n, _ in lora_names if n.strip()]
    return tags

def split_tag_query(query: str) -> list[str]:
    if not query or not query.strip():
        return []
    terms = []
    seen = set()
    for part in _RE_QUERY_SPLIT.split(query):
        q = norm_tag(part)
        if q and q not in seen:
            seen.add(q)
            terms.append(q)
    return terms

def tags_match(tags: list[str], queries: list[str], require_all: bool = False) -> bool:
    if not queries:
        return True
    norm_tags = [norm_tag(t) for t in tags if t and t.strip()]
    if not norm_tags:
        return False
    hits = [any(q in t for t in norm_tags) for q in queries]
    return all(hits) if require_all else any(hits)

def dedup_tags(text: str):
    if not text.strip(): return text, 0
    tokens = _split_prompt_tokens(text.strip())
    seen, out, removed = set(), [], 0
    for t in tokens:
        t_s = t.strip()
        if not t_s: continue
        if t_s.startswith("<lora:") and t_s.endswith(">"):
            k = _normalize_lora_token(t_s)
        else:
            # 正規表現(_RE_NORM)を廃止し純粋な文字列操作に置換（高速化 v1.80）
            k = t_s.lower().replace("_", " ")
            k = " ".join(k.split())
        if k not in seen:
            seen.add(k)
            out.append(t_s)
        else:
            removed += 1
    return ", ".join(out), removed

def _extract_raw_from_exif(img) -> str:
    """JPG/WebP/HEICのEXIF・XMPからSD生成パラメータ文字列を抽出する。
    取得に失敗した場合は空文字列を返す（例外を外に伝播しない）。
    """
    raw = ""

    # ── 1. EXIF UserComment (tag 0x9286 = 37510) ─────────────────────────
    try:
        exif_data = img.getexif() if hasattr(img, "getexif") else None
        if exif_data:
            uc = exif_data.get(0x9286, b"")
            if isinstance(uc, bytes) and len(uc) > 8:
                charset_id = uc[:8]
                body = uc[8:]
                try:
                    if charset_id.startswith(b"UNICODE"):
                        raw = body.decode("utf-16-be", "ignore").strip("\x00").strip()
                    elif charset_id.startswith(b"ASCII"):
                        raw = body.decode("ascii", "ignore").strip("\x00").strip()
                    else:
                        raw = body.decode("utf-8", "ignore").strip("\x00").strip()
                except Exception:
                    pass
            # ImageDescription (tag 0x010E = 270) — 一部のSD実装が使う
            if not raw:
                desc = exif_data.get(0x010E, "")
                if isinstance(desc, str) and len(desc) > 20:
                    raw = desc
    except Exception:
        pass

    # ── 2. XMP ────────────────────────────────────────────────────────────
    if not raw:
        try:
            xmp_str = None
            # JPEG: APPリストからxmpmetaを探す
            if hasattr(img, "applist"):
                for seg, data in img.applist:
                    if seg == "APP1" and b"xmpmeta" in data:
                        try:
                            xmp_str = data.decode("utf-8", "ignore")
                        except Exception:
                            pass
                        break
            # Pillow info辞書にxmpキーがある場合
            if xmp_str is None:
                xmp_raw = (img.info or {}).get("xmp", None)
                if isinstance(xmp_raw, bytes):
                    xmp_str = xmp_raw.decode("utf-8", "ignore")
                elif isinstance(xmp_raw, str):
                    xmp_str = xmp_raw
            if xmp_str:
                for tag in ("xmp:Description", "dc:description", "exif:UserComment"):
                    m = re.search(
                        r"<" + tag + r"[^>]*>(.*?)</" + tag + r">",
                        xmp_str, re.DOTALL | re.IGNORECASE)
                    if m:
                        candidate = re.sub(r"<[^>]+>", "", m.group(1)).strip()
                        if len(candidate) > 20:
                            raw = candidate
                            break
        except Exception:
            pass

    # ── 3. info辞書のその他の値をフォールバックで検索 ────────────────────
    if not raw:
        try:
            for v in (img.info or {}).values():
                if isinstance(v, str) and len(v) > 20:
                    raw = v
                    break
        except Exception:
            pass

    return raw


def _read_png_text_chunks(path: str) -> dict:
    """PNGのtEXtチャンクをPillow不使用で直接バイナリ読み取りする（高速）。
    parameters / prompt キーのみ抽出して返す。失敗時は空dict。"""
    result = {}
    try:
        with open(path, "rb") as f:
            sig = f.read(8)
            if sig != b"\x89PNG\r\n\x1a\n":
                return result
            while True:
                hdr = f.read(8)
                if len(hdr) < 8:
                    break
                length = int.from_bytes(hdr[:4], "big")
                chunk_type = hdr[4:8]
                data = f.read(length)
                f.read(4)  # CRC
                if chunk_type == b"tEXt":
                    try:
                        nul = data.index(0)
                        key = data[:nul].decode("latin-1", "ignore")
                        val = data[nul+1:].decode("latin-1", "ignore")
                        result[key] = val
                        if "parameters" in result and "prompt" in result:
                            break  # 必要なキーが揃ったら早期終了
                    except Exception:
                        pass
                elif chunk_type in (b"IDAT", b"IEND"):
                    break  # 画像データより後にtEXtは来ない
    except Exception:
        pass
    return result


def parse_meta(path: str) -> dict:
    r = {"prompt": "", "negative": "", "param_line": "", "model": "", "loras": [],
         "steps": "", "cfg": "", "sampler": "", "seed": "",
         "width": "", "height": "", "date": "", "raw": "", "mtime": 0, "fsize": 0}

    # ── ファイル情報 ──────────────────────────────────────────────────────
    try:
        s = os.stat(path)
        r["mtime"] = s.st_mtime
        r["fsize"] = s.st_size
        r["date"] = datetime.fromtimestamp(s.st_mtime).strftime("%Y-%m-%d %H:%M")
    except Exception as e:
        r["raw"] = f"[ファイル情報取得エラー: {e}]"
        return r

    # ── 画像サイズ取得（QImageReader: ピクセル展開しないため高速）────────
    try:
        reader = QImageReader(path)
        sz = reader.size()
        if sz.isValid() and sz.width() > 0:
            r["width"]  = str(sz.width())
            r["height"] = str(sz.height())
    except Exception:
        pass

    # ── rawパラメータ文字列の取得 ─────────────────────────────────────────
    try:
        ext = os.path.splitext(path)[1].lower()
        raw = ""

        # PNG: tEXtチャンクを直接バイナリ読み取り（Pillow不使用・高速）
        if ext == ".png":
            chunks = _read_png_text_chunks(path)
            raw = chunks.get("parameters", "") or chunks.get("prompt", "")

        # JPG / WebP / その他: Pillow でEXIF・XMP抽出（遅延ロードのまま）
        if not raw:
            try:
                img = Image.open(path)
                # img.info はヘッダーのみ（ピクセル展開なし）
                info = img.info or {}
                if not raw:
                    raw = info.get("parameters", "") or info.get("prompt", "")
                if not raw:
                    raw = _extract_raw_from_exif(img)
            except Exception:
                pass

        r["raw"] = raw
    except Exception as e:
        r["raw"] = f"[メタ取得エラー: {e}]"
        return r

    if not r["raw"]:
        return r

    # ── SD生成パラメータ解析 ──────────────────────────────────────────────
    try:
        raw = r["raw"]
        neg = _RE_NEG.split(raw)
        r["prompt"] = neg[0].strip()
        rest = neg[1] if len(neg) > 1 else ""
        if rest:
            sp = _RE_STEPS.split(rest)
            r["negative"] = sp[0].strip()
            r["param_line"] = ("Steps:" + sp[1].strip()) if len(sp) > 1 else ""
        else:
            sp = _RE_STEPS.split(raw)
            r["prompt"] = sp[0].strip()
            r["param_line"] = ("Steps:" + sp[1].strip()) if len(sp) > 1 else ""
        pl = r["param_line"]

        def ex(pat, t):
            try:
                m = re.search(pat, t, re.I)
                return m.group(1).strip() if m else ""
            except Exception:
                return ""

        r["steps"]   = ex(r"Steps:\s*(\d+)", pl)
        r["cfg"]     = ex(r"CFG scale:\s*([\d.]+)", pl)
        r["sampler"] = ex(r"Sampler:\s*([^,]+)", pl)
        r["seed"]    = ex(r"Seed:\s*(\d+)", pl)
        r["model"]   = ex(r"Model:\s*([^,\n]+)", pl)
        r["loras"] = list(dict.fromkeys(
            [n for n, _ in _RE_LORA.findall(r["prompt"])] +
            [n for n, _ in _RE_LORA.findall(r["param_line"])]
        ))
    except Exception as e:
        r["raw"] += f"\n[パラメータ解析エラー: {e}]"
    return r

def rebuild_params(pos: str, neg: str, pl: str) -> str:
    parts = [pos.strip()]
    if neg.strip(): parts.append(f"\nNegative prompt: {neg.strip()}")
    if pl.strip():  parts.append(f"\n{pl.strip()}")
    return "".join(parts)

def save_png_params(src: str, parameters: str):
    shutil.copy2(src, src + ".bak")
    with open(src, "rb") as f: raw = f.read()
    if not raw.startswith(b"\x89PNG\r\n\x1a\n"): raise ValueError("PNGではありません")
    def mk(kw, txt):
        d = (kw + "\x00" + txt).encode("latin-1", "replace")
        c = zlib.crc32(b"tEXt" + d) & 0xFFFFFFFF
        return struct.pack(">I", len(d)) + b"tEXt" + d + struct.pack(">I", c)
    out = [b"\x89PNG\r\n\x1a\n"]; p = 8; ins = False
    while p < len(raw):
        ln = struct.unpack(">I", raw[p:p+4])[0]; ct = raw[p+4:p+8]
        chunk = raw[p:p+12+ln]; p += 12 + ln
        if ct == b"tEXt":
            kw = chunk[8:8+ln].split(b"\x00", 1)[0].decode("latin-1", "replace")
            if kw == "parameters":
                if not ins: out.append(mk("parameters", parameters)); ins = True
                continue
        out.append(chunk)
        if ct == b"IHDR" and not ins: out.append(mk("parameters", parameters)); ins = True
    with open(src, "wb") as f:
        for c in out: f.write(c)

# ── サムネキャッシュ ──────────────────────────────────────────────────────
_mem: dict = {}
_mem_lock = threading.Lock()  # _mem の読み書きを保護するロック

def _cache_key(path: str, size: int) -> Path:
    try: mt = f"{os.path.getmtime(path):.0f}"
    except: mt = "0"
    h = hashlib.md5(f"{path}:{size}:{mt}".encode()).hexdigest()
    return CACHE_DIR / f"{h}.raw"

def load_thumb_image(path: str, size: int) -> QImage | None:
    k = f"{path}:{size}"
    with _mem_lock:
        if k in _mem:
            cached = _mem[k]
            if isinstance(cached, QImage):
                return cached
            if isinstance(cached, QPixmap):
                return cached.toImage()
            return None
    ck = _cache_key(path, size)
    try:
        if ck.exists():
            raw = ck.read_bytes()
            if raw[:4] == b"RAWX":
                # ヘッダー構造 (v1.86改訂):
                #   [0:4]  = b"RAWX"
                #   [4:6]  = width  (uint16 LE)
                #   [6:8]  = height (uint16 LE)
                #   [8]    = channels (3=RGB, 4=RGBA)
                #   [9:11] = bytesPerLine (uint16 LE)  ← v1.86追加 (旧形式=0でフォールバック)
                #   [11:]  = raw pixel data (stride込み)
                # ⚠ 旧形式(9バイトヘッダー)との後方互換: bpl=0 なら w*ch で代替
                w   = int.from_bytes(raw[4:6], "little")
                h   = int.from_bytes(raw[6:8], "little")
                ch  = raw[8]
                bpl = int.from_bytes(raw[9:11], "little") if len(raw) > 11 else 0
                fmt = QImage.Format.Format_RGB888 if ch == 3 else QImage.Format.Format_RGBA8888
                img_data = raw[11:] if bpl > 0 else raw[9:]
                bpl = bpl if bpl > 0 else w * ch
                qi  = QImage(img_data, w, h, bpl, fmt).copy()
            else:
                d = pickle.loads(raw)
                pil = Image.frombytes(d["mode"], d["size"], d["data"])
                qi = pil_to_qimage(pil)
        else:
            qi = None

            # ── 優先: QImageReader によるネイティブ縮小読み込み ────────────
            # Qt 内蔵デコーダを使うため JPEG のデコード段階でダウンサンプリングが
            # 行われ、Pillow より高速かつ省メモリ。
            # ※ QPixmap はバックグラウンドスレッドで作成不可（Qt規約）なので
            #    QImage まで生成し、QPixmap.fromImage() は共通パスで実施する。
            reader = QImageReader(path)
            reader.setAutoTransform(True)   # EXIF回転を自動適用
            if reader.canRead():
                orig = reader.size()
                if orig.isValid() and orig.width() > 0 and orig.height() > 0:
                    ow, oh = orig.width(), orig.height()
                    if ow > size or oh > size:
                        ratio = min(size / ow, size / oh)
                        reader.setScaledSize(QSize(int(ow * ratio), int(oh * ratio)))
                qimg = reader.read()
                if not qimg.isNull():
                    # アルファ有無に応じてフォーマット統一
                    if qimg.hasAlphaChannel():
                        qi = qimg.convertToFormat(QImage.Format.Format_RGBA8888).copy()
                    else:
                        qi = qimg.convertToFormat(QImage.Format.Format_RGB888).copy()

                    # キャッシュをバックグラウンドで書き込み（QRunnable 利用）
                    class _SaveQImg(QRunnable):
                        def __init__(self, p, qi):
                            super().__init__(); self.p = p; self.qi = qi
                        def run(self):
                            try:
                                ch  = 4 if self.qi.hasAlphaChannel() else 3
                                bpl = self.qi.bytesPerLine()  # ⚠ stride必須
                                header = (b"RAWX"
                                          + self.qi.width().to_bytes(2, "little")
                                          + self.qi.height().to_bytes(2, "little")
                                          + bytes([ch])
                                          + bpl.to_bytes(2, "little"))  # v1.86追加
                                self.p.write_bytes(header + bytes(self.qi.constBits()))
                            except: pass
                    QThreadPool.globalInstance().start(_SaveQImg(ck, qi.copy()))

            # ── フォールバック: Pillow（QImageReader が対応しない形式用）────
            if qi is None:
                pil = Image.open(path)
                ext = os.path.splitext(path)[1].lower()
                if ext in (".jpg", ".jpeg"):
                    try:
                        pil.draft("RGB", (size, size))
                        pil = Image.open(path)
                        pil.draft("RGB", (size, size))
                    except Exception:
                        pass
                # BILINEAR: BICUBIC より軽量で、サムネサイズでは品質差が小さい
                pil.thumbnail((size, size), Image.BILINEAR)
                qi = pil_to_qimage(pil)

                class _SavePil(QRunnable):
                    def __init__(self, p, img):
                        super().__init__(); self.p = p; self.img = img
                    def run(self):
                        try:
                            ch  = 3 if self.img.mode == "RGB" else 4
                            bpl = self.img.width * ch  # Pillow tobytes() はパディングなし
                            header = (b"RAWX"
                                      + self.img.width.to_bytes(2, "little")
                                      + self.img.height.to_bytes(2, "little")
                                      + bytes([ch])
                                      + bpl.to_bytes(2, "little"))  # v1.86追加
                            self.p.write_bytes(header + self.img.tobytes())
                        except:
                            pass
                QThreadPool.globalInstance().start(_SavePil(ck, pil))

        if qi is not None:
            with _mem_lock:
                if len(_mem) > 1200:
                    for old in list(_mem)[:300]: del _mem[old]
                _mem[k] = qi.copy()
        return qi
    except:
        return None

def load_thumb(path: str, size: int) -> QPixmap | None:
    qi = load_thumb_image(path, size)
    if qi is None:
        return None
    if isinstance(qi, QImage):
        return QPixmap.fromImage(qi.copy())
    return qi if isinstance(qi, QPixmap) else None

def load_preview_image(path: str, max_w: int, max_h: int) -> QImage | None:
    """プレビュー用: QImageReaderで高速に読み込み、アスペクト比を保ちつつ
    max_w×max_h に収める。Pillowより高速でメモリ効率が良い（v1.80）。
    キャッシュキーはパスのみ（サイズ違いで増殖しない）。"""
    k = f"__prev__{path}"
    with _mem_lock:
        if k in _mem:
            cached = _mem[k]
            if isinstance(cached, QImage):
                return cached
            if isinstance(cached, QPixmap):
                return cached.toImage()
            return None
    try:
        reader = QImageReader(path)
        reader.setAutoTransform(True)
        if reader.canRead():
            orig = reader.size()
            if orig.isValid() and orig.width() > 0 and orig.height() > 0:
                ow, oh = orig.width(), orig.height()
                # デコード段階で縮小指示（I/O・メモリ節約）
                if ow > 1600 or oh > 1600:
                    ratio = min(1600 / ow, 1600 / oh)
                    reader.setScaledSize(QSize(int(ow * ratio), int(oh * ratio)))
            qimg = reader.read()
            if not qimg.isNull():
                if qimg.hasAlphaChannel():
                    qimg = qimg.convertToFormat(QImage.Format.Format_RGBA8888)
                else:
                    qimg = qimg.convertToFormat(QImage.Format.Format_RGB888)
                with _mem_lock:
                    if len(_mem) > 1200:
                        for old_k in list(_mem)[:300]: del _mem[old_k]
                    _mem[k] = qimg.copy()
                return qimg.copy()

        # QImageReader未対応フォーマット用 Pillow フォールバック
        pil = Image.open(path)
        pil.thumbnail((1600, 1600), Image.BILINEAR)
        qimg = pil_to_qimage(pil)
        with _mem_lock:
            if len(_mem) > 1200:
                for old_k in list(_mem)[:300]: del _mem[old_k]
            _mem[k] = qimg.copy()
        return qimg.copy()
    except:
        return None

def load_preview_pixmap(path: str, max_w: int, max_h: int) -> QPixmap | None:
    qi = load_preview_image(path, max_w, max_h)
    if qi is None:
        return None
    if isinstance(qi, QImage):
        return QPixmap.fromImage(qi.copy())
    return qi if isinstance(qi, QPixmap) else None

def pil_to_qpixmap(pil_img: Image.Image) -> QPixmap:
    qi = pil_to_qimage(pil_img)
    return QPixmap.fromImage(qi.copy())

def pil_to_qimage(pil_img: Image.Image) -> QImage:
    if pil_img.mode not in ("RGB", "RGBA"):
        pil_img = pil_img.convert("RGBA")
    data = pil_img.tobytes()
    ch = len(pil_img.getbands())
    fmt = QImage.Format.Format_RGB888 if ch == 3 else QImage.Format.Format_RGBA8888
    return QImage(data, pil_img.width, pil_img.height, pil_img.width * ch, fmt).copy()

def as_pixmap(value):
    if isinstance(value, QPixmap):
        return value
    if isinstance(value, QImage):
        return QPixmap.fromImage(value.copy())
    return None

def clear_cache():
    with _mem_lock:
        _mem.clear()
    for f in CACHE_DIR.glob("*.raw"):
        try: f.unlink()
        except: pass

def avg_hash(path: str, size: int = 8) -> int | None:
    try:
        img = Image.open(path).convert("L").resize((size, size), Image.LANCZOS)
        px = list(img.getdata()); avg = sum(px) / len(px)
        return sum(1 << i for i, p in enumerate(px) if p >= avg)
    except: return None

def hamming(a: int, b: int) -> int:
    return bin(a ^ b).count("1")

def file_sha256(path: str, chunk_size: int = 1024 * 1024) -> str | None:
    try:
        h = hashlib.sha256()
        with open(path, "rb") as f:
            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    break
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return None

def human_file_size(size: int) -> str:
    try:
        size = int(size)
    except Exception:
        return "?"
    if size < 1024:
        return f"{size} B"
    if size < 1024 * 1024:
        return f"{size / 1024:.1f} KB"
    if size < 1024 * 1024 * 1024:
        return f"{size / (1024 * 1024):.2f} MB"
    return f"{size / (1024 * 1024 * 1024):.2f} GB"

# ── メタキャッシュ ────────────────────────────────────────────────────────
# ══════════════════════════════════════════════════════════════════════════════
#  削除確認ダイアログ（キーボード操作対応）
# ══════════════════════════════════════════════════════════════════════════════
class _DeleteConfirmDialog(QDialog):
    """削除確認ダイアログ。キーボードで完全操作可能。
    操作方法:
      Y / Enter       → 現在フォーカスのボタンを実行
      N / Esc         → いいえ（キャンセル）
      ← → / Tab      → 「はい」⇔「いいえ」でフォーカス移動
    デフォルトフォーカスは「はい」。
    """
    def __init__(self, title: str, message: str, permanent: bool = False, parent=None):
        super().__init__(parent)
        self.setModal(True)
        self.setWindowFlag(Qt.WindowType.WindowContextHelpButtonHint, False)
        self.setMinimumWidth(380)
        self.setAutoFillBackground(True)
        self.setStyleSheet(f"background:{PAL['bg2']};color:{PAL['fg1']};")
        self._result = False
        self._focus_yes = True   # True=はいにフォーカス、False=いいえにフォーカス

        root = QVBoxLayout(self)
        root.setContentsMargins(20, 16, 20, 16)
        root.setSpacing(16)

        # アイコン＋メッセージ
        icon_row = QHBoxLayout()
        icon_lbl = QLabel("⚠" if permanent else "🗑")
        icon_lbl.setStyleSheet("font-size: 28px;")
        icon_lbl.setFixedWidth(42)
        icon_lbl.setFixedHeight(42)
        icon_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        msg_lbl = QLabel(message)
        msg_lbl.setWordWrap(True)
        msg_lbl.setStyleSheet(f"color: {PAL['fg0']}; font-size: 10pt;")
        self._icon_lbl = icon_lbl
        self._msg_lbl = msg_lbl
        icon_row.addWidget(icon_lbl)
        icon_row.addWidget(msg_lbl, 1)
        root.addLayout(icon_row)

        # ヒント
        hint = QLabel("←→/Tab でボタン選択　　Enter/Y = はい　　N/Esc = いいえ")
        hint.setStyleSheet(f"color: {PAL['fg3']}; font-size: 8pt;")
        hint.setAlignment(Qt.AlignmentFlag.AlignCenter)
        root.addWidget(hint)

        # ボタン行
        btn_row = QHBoxLayout()
        btn_row.addStretch()

        self._yes_btn = QPushButton("はい(Y)")
        self._yes_btn.setFixedHeight(32)
        self._yes_btn.setMinimumWidth(100)
        self._yes_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self._yes_btn.clicked.connect(self._accept)

        self._no_btn = QPushButton("いいえ(N)")
        self._no_btn.setFixedHeight(32)
        self._no_btn.setMinimumWidth(100)
        self._no_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self._no_btn.clicked.connect(self.reject)

        btn_row.addWidget(self._yes_btn)
        btn_row.addSpacing(8)
        btn_row.addWidget(self._no_btn)
        root.addLayout(btn_row)

        # ダイアログ自体がキーフォーカスを持つ
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)

        self._permanent = permanent
        self.configure(title, message, permanent)

    def configure(self, title: str, message: str, permanent: bool = False, preview: QPixmap | None = None):
        self.setWindowTitle(title)
        self._permanent = permanent
        self._result = False
        self._focus_yes = True
        if preview and not preview.isNull():
            self._icon_lbl.clear()
            self._icon_lbl.setPixmap(preview.scaled(
                42, 42,
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation,
            ))
        else:
            self._icon_lbl.clear()
            std_icon = self.style().standardIcon(
                QStyle.StandardPixmap.SP_MessageBoxWarning
                if permanent else
                QStyle.StandardPixmap.SP_TrashIcon
            )
            icon_px = std_icon.pixmap(42, 42)
            if icon_px.isNull():
                icon_px = QPixmap(42, 42)
                icon_px.fill(Qt.GlobalColor.transparent)
                qp = QPainter(icon_px)
                qp.setRenderHint(QPainter.RenderHint.Antialiasing, True)
                qp.setPen(QColor(PAL["fg0"]))
                qp.setFont(QFont("Segoe UI Emoji", 26))
                qp.drawText(icon_px.rect(), Qt.AlignmentFlag.AlignCenter, "⚠" if permanent else "🗑")
                qp.end()
            self._icon_lbl.setPixmap(icon_px)
        self._msg_lbl.setText(message)
        self._update_focus_style()

    def exec_immediate(self) -> int:
        """白画面のまま待ち状態にならないよう、先に描画を済ませてから開く。"""
        self.ensurePolished()
        if self.layout():
            self.layout().activate()
        self.adjustSize()
        return self.exec()

    @staticmethod
    def ask(parent, title: str, message: str, permanent: bool = False, preview: QPixmap | None = None) -> bool:
        host = parent.window() if parent is not None and hasattr(parent, "window") else parent
        dlg = getattr(host, "_delete_confirm_dialog", None) if host is not None else None
        if dlg is None:
            dlg = _DeleteConfirmDialog(title, message, permanent=permanent, parent=parent)
            dlg.configure(title, message, permanent=permanent, preview=preview)
            if host is not None:
                host._delete_confirm_dialog = dlg
        else:
            dlg.configure(title, message, permanent=permanent, preview=preview)
        dlg.exec_immediate()
        return dlg.confirmed()

    def _update_focus_style(self):
        """フォーカス中のボタンを視覚的に強調する"""
        accent  = PAL['accent']
        danger  = PAL.get('red', '#e05555')
        base_yes = "danger" if self._permanent else "accent"

        # yes ボタン
        if self._focus_yes:
            hl_color = danger if self._permanent else accent
            self._yes_btn.setStyleSheet(
                f"QPushButton{{background:{hl_color};color:#fff;"
                f"border:2px solid #fff;border-radius:4px;padding:0 12px;font-weight:bold;}}"
                f"QPushButton:hover{{background:{hl_color};}}"
            )
            self._no_btn.setStyleSheet("")
        else:
            self._yes_btn.setStyleSheet("")
            self._no_btn.setStyleSheet(
                f"QPushButton{{background:{PAL['bg4']};color:{PAL['fg0']};"
                f"border:2px solid #fff;border-radius:4px;padding:0 12px;font-weight:bold;}}"
                f"QPushButton:hover{{background:{PAL['bg4']};}}"
            )

    def _toggle_focus(self):
        self._focus_yes = not self._focus_yes
        self._update_focus_style()

    def _accept(self):
        self._result = True
        self.accept()

    def keyPressEvent(self, e):
        k = e.key()
        if k == Qt.Key.Key_Y:
            self._accept()
        elif k in (Qt.Key.Key_N, Qt.Key.Key_Escape):
            self.reject()
        elif k in (Qt.Key.Key_Left, Qt.Key.Key_Right, Qt.Key.Key_Tab):
            self._toggle_focus()
        elif k in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
            # 現在フォーカスのボタンを実行
            if self._focus_yes:
                self._accept()
            else:
                self.reject()
        else:
            super().keyPressEvent(e)

    def confirmed(self) -> bool:
        return self._result


class MetaCache:
    """スレッドセーフなメタデータキャッシュ。
    ThumbLoader / PreloadWorker が複数スレッドから同時に get() を呼んでも
    データ競合が起きないよう threading.Lock で排他制御する。
    _MAX_META_ENTRIES を超えた場合は古い 20% のエントリを evict する（LRU近似）。
    save_to_disk / load_from_disk でアプリ再起動をまたいでキャッシュを永続化する（v2.02）。
    """
    _MAX_META_ENTRIES = 50000  # この件数を超えたら古いエントリを削除（3万枚対応）
    _CACHE_FILE = APP_DIR / "meta_cache.pkl"

    def __init__(self):
        self._d: dict = {}
        self._lock = threading.Lock()
        self.load_from_disk()

    def load_from_disk(self):
        """アプリ起動時にディスクからメタデータを読み込む"""
        if self._CACHE_FILE.exists():
            try:
                with open(self._CACHE_FILE, "rb") as f:
                    data = pickle.load(f)
                    if isinstance(data, dict):
                        with self._lock:
                            self._d = data
            except Exception as e:
                print(f"メタキャッシュの読み込みに失敗: {e}")

    def save_to_disk(self):
        """アプリ終了時にメタデータを永続化する"""
        with self._lock:
            # 容量オーバー時は古いものから削除
            if len(self._d) > self._MAX_META_ENTRIES:
                keys = list(self._d.keys())
                for k in keys[:len(self._d) - self._MAX_META_ENTRIES]:
                    self._d.pop(k, None)
            try:
                APP_DIR.mkdir(parents=True, exist_ok=True)
                with open(self._CACHE_FILE, "wb") as f:
                    pickle.dump(self._d, f)
            except Exception as e:
                print(f"メタキャッシュの保存に失敗: {e}")

    def get(self, p: str) -> dict:
        with self._lock:
            if p in self._d:
                # mtime チェック（外部で変更された場合に無効化）
                try:
                    cur_mtime = os.path.getmtime(p)
                    if self._d[p].get("mtime") == cur_mtime:
                        return self._d[p]
                except Exception:
                    pass
                # mtimeが変わっていたらキャッシュを無効化
                del self._d[p]
        meta = parse_meta(p)
        with self._lock:
            if p not in self._d:
                # LRU近似: 上限超過時に古い 20% を削除
                if len(self._d) >= self._MAX_META_ENTRIES:
                    evict_count = self._MAX_META_ENTRIES // 5
                    for old_key in list(self._d)[:evict_count]:
                        del self._d[old_key]
                self._d[p] = meta
            return self._d[p]

    def snapshot(self) -> dict:
        """現在のキャッシュ内容のコピーをロックを取得して返す。
        I/O を一切行わないため、ワーカースレッドから安全に呼べる。
        LoRA分析ワーカー等が meta_snap を作成する際にはこれを使う。"""
        with self._lock:
            return dict(self._d)

    def invalidate(self, p: str):
        with self._lock:
            self._d.pop(p, None)

    def clear(self):
        with self._lock:
            self._d.clear()
        try:
            if self._CACHE_FILE.exists():
                self._CACHE_FILE.unlink()
        except Exception:
            pass

META = MetaCache()


