#  ロゴオーバーレイ管理  (v2.03)
# ══════════════════════════════════════════════════════════════════════════════
class OverlayManager:
    """非破壊タイトルロゴ・オーバーレイ設定を管理する。
    overlay_data: {
        image_path: {
            "logo_path": str,
            "x_rel": float,
            "y_rel": float,
            "scale": float,
            "corner": str,
            "margin_rel": float,
        }
    }
    tag_to_logo:  {tag_name: logo_path}
    設定は APP_DIR/overlay_settings.json に自動保存。
    """
    _SAVE_FILE = APP_DIR / "overlay_settings.json"
    DEFAULT_CORNER = "bottom_right"
    DEFAULT_MARGIN_REL = 0.0
    MIN_MARGIN_REL = -0.5
    MAX_MARGIN_REL = 0.25

    def __init__(self):
        self.overlay_data: dict = {}
        self.tag_to_logo:  dict = {}
        self._load()

    def _normalize_entry(self, info: dict | None) -> dict | None:
        if not isinstance(info, dict):
            return None
        corner = str(info.get("corner", self.DEFAULT_CORNER) or self.DEFAULT_CORNER)
        if corner not in {"top_left", "top_right", "bottom_left", "bottom_right", "manual"}:
            corner = self.DEFAULT_CORNER
        try:
            margin_rel = float(info.get("margin_rel", self.DEFAULT_MARGIN_REL))
        except Exception:
            margin_rel = self.DEFAULT_MARGIN_REL
        margin_rel = max(self.MIN_MARGIN_REL, min(self.MAX_MARGIN_REL, margin_rel))
        try:
            x_rel = float(info.get("x_rel", 0.05))
        except Exception:
            x_rel = 0.05
        x_rel = max(-0.5, min(1.5, x_rel))
        try:
            y_rel = float(info.get("y_rel", 0.05))
        except Exception:
            y_rel = 0.05
        y_rel = max(-0.5, min(1.5, y_rel))
        try:
            scale = float(info.get("scale", 1.0))
        except Exception:
            scale = 1.0
        return {
            "logo_path": str(info.get("logo_path", "") or ""),
            "x_rel": max(0.0, min(1.0, x_rel)),
            "y_rel": max(0.0, min(1.0, y_rel)),
            "scale": max(0.05, scale),
            "corner": corner,
            "margin_rel": margin_rel,
        }

    def _load(self):
        try:
            if self._SAVE_FILE.exists():
                data = json.loads(self._SAVE_FILE.read_text("utf-8"))
                raw_overlay = data.get("overlay_data", {})
                self.overlay_data = {
                    path: norm
                    for path, norm in (
                        (path, self._normalize_entry(info))
                        for path, info in raw_overlay.items()
                    )
                    if norm
                }
                self.tag_to_logo  = data.get("tag_to_logo",  {})
        except Exception:
            pass

    def save(self):
        try:
            APP_DIR.mkdir(parents=True, exist_ok=True)
            self._SAVE_FILE.write_text(
                json.dumps({"overlay_data": self.overlay_data, "tag_to_logo": self.tag_to_logo},
                           ensure_ascii=False, indent=2), "utf-8")
        except Exception:
            pass

    def remap_logo_paths(self, path_map: dict[str, str]):
        """移動したロゴファイルの参照先を一括更新する。"""
        if not path_map:
            return
        changed = False
        for info in self.overlay_data.values():
            if not isinstance(info, dict):
                continue
            logo = str(info.get("logo_path", "") or "")
            new_logo = path_map.get(logo)
            if new_logo:
                info["logo_path"] = new_logo
                changed = True
        for tag, logo in list(self.tag_to_logo.items()):
            new_logo = path_map.get(str(logo or ""))
            if new_logo:
                self.tag_to_logo[tag] = new_logo
                changed = True
        if changed:
            self.save()

    def sync_logo_folder(self, new_dir: str | Path, move_existing: bool = False) -> tuple[Path, dict[str, str]]:
        """ロゴ保存先を変更し、必要なら既存ロゴを移動する。"""
        old_dir = get_logo_dir()
        new_dir = Path(new_dir).expanduser()
        if old_dir.resolve() == new_dir.resolve():
            return old_dir, {}
        new_dir.mkdir(parents=True, exist_ok=True)
        moved: dict[str, str] = {}
        if move_existing and old_dir.exists():
            for src in old_dir.iterdir():
                if not src.is_file():
                    continue
                dst = _unique_dest_path(new_dir, src.name)
                try:
                    shutil.move(str(src), str(dst))
                except Exception:
                    continue
                moved[str(src)] = str(dst)
        set_logo_dir(new_dir)
        return old_dir, moved

    def get(self, path: str) -> dict | None:
        info = self._normalize_entry(self.overlay_data.get(path))
        if info is None:
            return None
        self.overlay_data[path] = info
        return dict(info)

    def set_overlay(self, path: str, logo_path: str,
                    x_rel: float = 0.05, y_rel: float = 0.05, scale: float = 1.0,
                    corner: str = DEFAULT_CORNER,
                    margin_rel: float = DEFAULT_MARGIN_REL):
        self.overlay_data[path] = self._normalize_entry({
            "logo_path": logo_path,
            "x_rel": x_rel,
            "y_rel": y_rel,
            "scale": scale,
            "corner": corner,
            "margin_rel": margin_rel,
        })
        self.save()

    def remove(self, path: str):
        self.overlay_data.pop(path, None)
        self.save()

    def auto_apply(self, path: str, tags_str: str):
        """プロンプト文字列からタグを探し、tag_to_logo に一致があれば自動設定する。
        手動設定済みの画像はスキップ。"""
        if path in self.overlay_data:
            return
        if not tags_str or not self.tag_to_logo:
            return
        tags_lower = tags_str.lower()
        for tag, logo in self.tag_to_logo.items():
            if tag.lower() in tags_lower and os.path.isfile(logo):
                self.overlay_data[path] = self._normalize_entry({
                    "logo_path": logo,
                    "x_rel": 0.05,
                    "y_rel": 0.05,
                    "scale": 1.0,
                    "corner": self.DEFAULT_CORNER,
                    "margin_rel": self.DEFAULT_MARGIN_REL,
                })
                self.save()
                return

OVERLAY = OverlayManager()


class _ErrorDialog(QDialog):
    """コピーボタン付きエラーダイアログ。QMessageBox.critical の代替。"""
    def __init__(self, title: str, message: str, parent=None):
        super().__init__(parent)
        self.setWindowTitle(title)
        self.setModal(True)
        self.setMinimumWidth(440)
        root = QVBoxLayout(self)
        root.setContentsMargins(16, 14, 16, 12)
        root.setSpacing(10)
        icon_row = QHBoxLayout()
        icon_lbl = QLabel("⛔")
        icon_lbl.setStyleSheet("font-size:28px;")
        icon_lbl.setFixedWidth(42)
        msg_te = QPlainTextEdit(message)
        msg_te.setReadOnly(True)
        msg_te.setFont(QFont("Consolas", 8))
        msg_te.setStyleSheet(
            f"background:{PAL['bg3']};color:{PAL['fg0']};"
            f"border:1px solid {PAL['border']};border-radius:4px;")
        msg_te.setMinimumHeight(80)
        icon_row.addWidget(icon_lbl, 0, Qt.AlignmentFlag.AlignTop)
        icon_row.addWidget(msg_te, 1)
        root.addLayout(icon_row)
        btn_row = QHBoxLayout()
        copy_btn = QPushButton("📋 コピー")
        copy_btn.setToolTip("エラーメッセージをクリップボードにコピー")
        copy_btn.clicked.connect(lambda: QApplication.clipboard().setText(message))
        close_btn = QPushButton("閉じる")
        close_btn.setDefault(True)
        close_btn.clicked.connect(self.accept)
        btn_row.addWidget(copy_btn)
        btn_row.addStretch()
        btn_row.addWidget(close_btn)
        root.addLayout(btn_row)

    @staticmethod
    def show_error(title: str, message: str, parent=None):
        _ErrorDialog(title, message, parent).exec()


