#  Worker スレッド (QThread ベース)
# ══════════════════════════════════════════════════════════════════════════════
class ScanWorker(QThread):
    """フォルダスキャンスレッド。ファイルリストと同時に stat 辞書も返す。"""
    finished = Signal(list, dict)  # files, stats_dict {path: (mtime, ctime, size)}

    def __init__(self, root: str, sub: bool, exts: set, parent=None):
        super().__init__(parent)
        self._root = root; self._sub = sub
        self._exts = tuple(exts)  # endswith() 用タプル
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        files = []
        stats = {}
        exts = self._exts
        if self._sub:
            def _scan(dp: str):
                if self._cancelled: return
                try:
                    with os.scandir(dp) as it:
                        for entry in it:
                            if self._cancelled: return
                            if entry.is_dir(follow_symlinks=False):
                                _scan(entry.path)
                            elif entry.name.lower().endswith(exts):  # splitext より高速
                                if entry.is_file(follow_symlinks=False):
                                    p = entry.path
                                    files.append(p)
                                    try:
                                        st = entry.stat(follow_symlinks=False)
                                        stats[p] = (st.st_mtime, st.st_ctime, st.st_size)
                                    except:
                                        stats[p] = (0, 0, 0)
                except Exception:
                    pass
            _scan(self._root)
        else:
            try:
                with os.scandir(self._root) as it:
                    for entry in it:
                        if self._cancelled: break
                        if entry.name.lower().endswith(exts):  # splitext より高速
                            if entry.is_file(follow_symlinks=False):
                                p = entry.path
                                files.append(p)
                                try:
                                    st = entry.stat(follow_symlinks=False)
                                    stats[p] = (st.st_mtime, st.st_ctime, st.st_size)
                                except:
                                    stats[p] = (0, 0, 0)
            except Exception:
                pass
        if self._cancelled: return
        files.sort(key=lambda p: os.path.basename(p).lower())
        if not self._cancelled:
            self.finished.emit(files, stats)


class PreloadWorker(QThread):
    """メタデータ先読みスレッド（キャッシュ済みスキップ最適化版 v2.02）"""
    progress = Signal(int, int)
    done     = Signal()

    def __init__(self, files: list, stats: dict | None = None, parent=None):
        super().__init__(parent)
        self._files = list(files)
        self._stats = stats or {}   # {path: (mtime, ctime, size)} — ScanWorkerが提供
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        total = len(self._files)
        if total == 0:
            self.done.emit(); return

        completed = 0
        prog_lock = threading.Lock()

        # 解析が必要なファイルだけを抽出（キャッシュ済み & mtime一致 → スキップ）
        snap = META.snapshot()
        to_process = []
        for p in self._files:
            st = self._stats.get(p)
            # キャッシュにあり、かつ mtime が一致していればスキップ
            if p in snap and st and snap[p].get("mtime") == st[0]:
                completed += 1
                continue
            to_process.append(p)

        # すでに全件キャッシュ済みなら即終了
        if not to_process:
            self.progress.emit(total, total)
            self.done.emit()
            return

        def _process(p: str):
            if self._cancelled: return
            if p not in META._d:
                try: META.get(p)
                except: pass
            nonlocal completed
            with prog_lock:
                completed += 1
                c = completed
            # 進捗は 50 件ごとに送る（UI更新負荷を抑制）
            if c % 50 == 0 or c == total:
                if not self._cancelled:
                    self.progress.emit(c, total)

        # サムネ生成の I/O を阻害しないよう優先度低いバックグラウンドとして最大4スレッドに制限
        max_workers = min(4, os.cpu_count() or 4)
        with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
            futures = []
            for p in to_process:
                if self._cancelled: break
                futures.append(executor.submit(_process, p))
            # キャンセル時は未開始タスクを即座にキャンセル
            if self._cancelled:
                for f in futures:
                    f.cancel()

        if not self._cancelled:
            self.done.emit()


class FilterWorker(QThread):
    """フィルタ・ソートスレッド"""
    finished = Signal(list)

    def __init__(self, all_paths, tq, tag_and, mq, sq, rfilter, qfilter, ratings, quality_cache, sort_key, sort_rev, meta_snap, stats_dict=None, parent=None):
        super().__init__(parent)
        self._paths = all_paths; self._tq = tq; self._mq = mq; self._sq = sq
        self._tag_and = tag_and
        self._rf = rfilter; self._qf = qfilter; self._ratings = ratings; self._quality = quality_cache
        self._key = sort_key; self._rev = sort_rev
        self._meta = meta_snap; self._stats = stats_dict or {}
        self._cancelled = False

    def cancel(self): self._cancelled = True

    def run(self):
        tq = self._tq; mq = self._mq; sq = self._sq; rf = self._rf; qf = self._qf
        tq_terms = split_tag_query(tq)
        no_filter = (not tq and not mq and not sq and rf == "all" and qf == "all")
        if no_filter:
            filtered = list(self._paths)
        else:
            filtered = []
            for p in self._paths:
                if self._cancelled: return
                m = self._meta.get(p)
                # ⚠ 同期パース（META.get → Image.open）によるフリーズを完全防止。
                # 未キャッシュファイルはスキップし、PreloadWorker の進捗に合わせて
                # _on_preload_progress が定期的に _apply_filter() を再実行することで
                # シームレスに結果が増えていく設計にする。
                if m is None:
                    continue
                if tq:
                    search_tags = (
                        tag_list(m.get("prompt", ""))
                        + tag_list(m.get("negative", ""))
                        + list(m.get("loras", []))
                    )
                    hit = tags_match(search_tags, tq_terms, self._tag_and)
                    if not hit: continue
                if mq and m.get("model") != mq: continue
                if sq and sq not in str(m.get("seed", "")).strip(): continue
                if rf != "all":
                    r = self._ratings.get(p, 0)
                    if rf == "未評価" and r != 0: continue
                    elif rf == "★5" and r != 5: continue
                    elif rf == "★4+" and r < 4: continue
                    elif rf == "★3+" and r < 3: continue
                    elif rf == "★2+" and r < 2: continue
                    elif rf == "★1+" and r < 1: continue
                if qf != "all":
                    qinfo = self._quality.get(p, {})
                    qlabel = str(qinfo.get("label", "unknown"))
                    if qlabel != qf:
                        continue
                filtered.append(p)

        if self._cancelled: return
        key = self._key; rev = self._rev; meta = self._meta; stats = self._stats
        if key == "name":
            filtered.sort(key=lambda p: os.path.basename(p).lower(), reverse=rev)
        elif key == "path":
            filtered.sort(key=lambda p: p.lower(), reverse=rev)
        elif key == "date":
            # 事前取得済み stat を使い os.stat() 呼び出しをゼロに（3万枚でも即完了）
            filtered.sort(key=lambda p: stats.get(p, (0, 0, 0))[0], reverse=rev)
        elif key == "cdate":
            filtered.sort(key=lambda p: stats.get(p, (0, 0, 0))[1], reverse=rev)
        elif key == "size":
            filtered.sort(key=lambda p: stats.get(p, (0, 0, 0))[2], reverse=rev)
        elif key == "imgsize":
            # Image.open フォールバックは大量ファイル時にフリーズするため廃止
            def _is(p):
                m = meta.get(p)
                if m:
                    try: return int(m.get("width", 0) or 0) * int(m.get("height", 0) or 0)
                    except: pass
                return 0
            filtered.sort(key=_is, reverse=rev)
        elif key == "random":
            random.shuffle(filtered)

        if not self._cancelled:
            self.finished.emit(filtered)


class TagCountWorker(QThread):
    """タグ集計スレッド"""
    finished = Signal(list)

    def __init__(self, paths, meta_snap, query="", parent=None):
        super().__init__(parent)
        self._paths = list(paths); self._meta = meta_snap; self._q = query
        self._cancelled = False

    def cancel(self): self._cancelled = True

    def run(self):
        counter = Counter()
        for p in self._paths:
            if self._cancelled: return
            m = self._meta.get(p)
            # ⚠ 同期パースによるフリーズを防止。未キャッシュはスキップ。
            if not m:
                continue
            for t in tag_list(m.get("prompt", "")): counter[norm_tag(t)] += 1
        q = norm_tag(self._q)
        items = [(k, v) for k, v in counter.most_common() if q in k]
        if not self._cancelled:
            self.finished.emit(items)


class ModelListWorker(QThread):
    """モデルリスト集計スレッド（安定したQThreadサブクラス）"""
    finished = Signal(list)

    def __init__(self, all_paths: list, meta_snap: dict, parent=None):
        super().__init__(parent)
        self._paths = list(all_paths)
        self._meta  = meta_snap
        self._cancelled = False

    def cancel(self): self._cancelled = True

    def run(self):
        models = set()
        for p in self._paths:
            if self._cancelled: return
            m = self._meta.get(p)
            if m and m.get("model"): models.add(m["model"])
        if not self._cancelled:
            self.finished.emit(sorted(models))


class DuplicateDetectWorker(QThread):
    """重複画像検出ワーカー。
    完全一致は SHA-256、類似は知覚ハッシュ(avg_hash) のハミング距離で判定する。
    """
    progress = Signal(str)
    finished = Signal(list, dict)

    def __init__(self, paths: list, stats: dict | None = None, meta_snap: dict | None = None,
                 similarity_threshold: int = 5, parent=None):
        super().__init__(parent)
        self._paths = list(paths)
        self._stats = stats or {}
        self._meta = meta_snap or {}
        self._threshold = similarity_threshold
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def _dims(self, path: str) -> tuple[int, int]:
        m = self._meta.get(path) or {}
        try:
            w = int(m.get("width", 0) or 0)
            h = int(m.get("height", 0) or 0)
            if w > 0 and h > 0:
                return w, h
        except Exception:
            pass
        try:
            with Image.open(path) as img:
                return img.width, img.height
        except Exception:
            return (0, 0)

    def run(self):
        existing = [p for p in self._paths if os.path.isfile(p)]
        summary = {
            "scanned": len(existing),
            "exact_groups": 0,
            "similar_groups": 0,
            "duplicate_files": 0,
        }
        if not existing or self._cancelled:
            self.finished.emit([], summary)
            return

        self.progress.emit("重複画像: 完全一致を検出中...")
        size_buckets: dict[int, list[str]] = {}
        for p in existing:
            size_buckets.setdefault(self._stats.get(p, (0, 0, os.path.getsize(p)))[2], []).append(p)

        groups = []
        consumed = set()
        gid = 1
        for plist in size_buckets.values():
            if self._cancelled:
                return
            if len(plist) < 2:
                continue
            digest_map: dict[str, list[str]] = {}
            for p in plist:
                digest = file_sha256(p)
                if not digest:
                    continue
                digest_map.setdefault(digest, []).append(p)
            for digest, dup_paths in digest_map.items():
                if len(dup_paths) < 2:
                    continue
                dup_paths = sorted(dup_paths)
                groups.append({
                    "id": gid,
                    "mode": "完全一致",
                    "label": digest[:12],
                    "paths": dup_paths,
                })
                gid += 1
                consumed.update(dup_paths)
                summary["exact_groups"] += 1
                summary["duplicate_files"] += len(dup_paths) - 1

        self.progress.emit("重複画像: 類似画像を検出中...")
        remaining = [p for p in existing if p not in consumed]
        buckets: dict[tuple[int, int, int], list[tuple[str, int]]] = {}
        for idx, p in enumerate(remaining, 1):
            if self._cancelled:
                return
            ah = avg_hash(p)
            if ah is None:
                continue
            w, h = self._dims(p)
            key = (max(1, w // 64), max(1, h // 64), ah >> 56)
            buckets.setdefault(key, []).append((p, ah))
            if idx % 300 == 0:
                self.progress.emit(f"重複画像: 類似ハッシュ計算中... {idx}/{len(remaining)}")

        visited = set()
        for items in buckets.values():
            if self._cancelled:
                return
            n = len(items)
            if n < 2:
                continue
            for i in range(n):
                p, ah = items[i]
                if p in visited:
                    continue
                grp = [p]
                for j in range(i + 1, n):
                    q, bh = items[j]
                    if q in visited:
                        continue
                    if hamming(ah, bh) <= self._threshold:
                        grp.append(q)
                if len(grp) > 1:
                    grp = sorted(grp)
                    groups.append({
                        "id": gid,
                        "mode": "類似",
                        "label": f"Δ<={self._threshold}",
                        "paths": grp,
                    })
                    gid += 1
                    visited.update(grp)
                    summary["similar_groups"] += 1
                    summary["duplicate_files"] += len(grp) - 1

        groups.sort(key=lambda g: (g["mode"] != "完全一致", -len(g["paths"]), g["paths"][0].lower()))
        self.progress.emit(f"重複画像: {len(groups)}グループを検出")
        self.finished.emit(groups, summary)


class SimilarFindWorker(QThread):
    progress = Signal(int, int, str)
    finished = Signal(list, str)

    def __init__(self, base_path: str, paths: list[str], threshold: int = 8, parent=None):
        super().__init__(parent)
        self._base = base_path
        self._paths = list(paths)
        self._threshold = threshold
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        base_h = avg_hash(self._base)
        if base_h is None or self._cancelled:
            self.finished.emit([self._base], self._base)
            return
        total = max(1, len(self._paths))
        self.progress.emit(0, total, "類似画像を検索中...")
        results = [self._base]
        for idx, p in enumerate(self._paths, 1):
            if self._cancelled:
                return
            if p != self._base:
                h = avg_hash(p)
                if h is not None and hamming(base_h, h) <= self._threshold:
                    results.append(p)
            if idx % 200 == 0 or idx == total:
                self.progress.emit(idx, total, "類似画像を検索中...")
        self.finished.emit(results, self._base)


class ThumbLoader(QRunnable):
    """サムネイル非同期ローダー (QThreadPool)
    キャンセルフラグ付き。削除済みセルへの配送はグリッド側で無視する。
    """
    class Signals(QObject):
        loaded = Signal(str, object)

    def __init__(self, path: str, size: int, generation: int):
        super().__init__()
        self.path = path; self.size = size; self.generation = generation
        self.signals = ThumbLoader.Signals()
        self.setAutoDelete(True)
        self._cancelled = False

    def cancel(self): self._cancelled = True

    def run(self):
        if self._cancelled: return
        img = load_thumb_image(self.path, self.size)
        if img is not None and not self._cancelled:
            self.signals.loaded.emit(self.path, img)



