    def _update_preview(self, path: str):
        """右パネル上部プレビューを更新（レイアウトB用）。非同期化 v1.80"""
        if not hasattr(self, "_preview_label"):
            return
        lbl = self._preview_label
        if not path:
            lbl.clear()
            lbl.setProperty("_preview_path", None)
            return
        pw = max(lbl.width(), 200)
        ph = max(lbl.height(), 160)
        self._load_preview_async(path, lbl, pw, ph)

    def _queue_preview_resize(self, lbl: QLabel, delay_ms: int = 80):
        """Coalesce rapid resize events before re-scaling cached preview pixmaps."""
        p = lbl.property("_preview_path")
        if not p:
            return
        timer_name = "_preview_resize_timer"
        timer = getattr(lbl, timer_name, None)
        if timer is None:
            timer = QTimer(lbl)
            timer.setSingleShot(True)
            setattr(lbl, timer_name, timer)

            def _refresh(_lbl=lbl):
                self._refresh_cached_preview(_lbl)

            timer.timeout.connect(_refresh)
        timer.start(delay_ms)

    def _refresh_cached_preview(self, lbl: QLabel):
        """Scale the cached preview to the label's current size."""
        p = lbl.property("_preview_path")
        if not p:
            return
        k = f"__prev__{p}"
        with _mem_lock:
            cached = _mem.get(k)
        if not cached:
            return
        cached_px = as_pixmap(cached)
        if cached_px is None:
            return
        pw2 = max(lbl.width(), 10)
        ph2 = max(lbl.height(), 10)
        composed = self._compose_overlay(cached_px, p, pw2, ph2)
        if composed is not cached_px:
            lbl.setPixmap(composed)
        else:
            lbl.setPixmap(cached_px.scaled(pw2, ph2,
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation))

