# ══════════════════════════════════════════════════════════════════════════════
#  エントリポイント
# ══════════════════════════════════════════════════════════════════════════════
def main():
    # Windows: python.exe で起動された場合は pythonw.exe で再起動してコンソールを消す
    if sys.platform == "win32":
        import ctypes
        # まず即座にコンソールを隠す（再起動前の一瞬も見えないように）
        try:
            ctypes.windll.user32.ShowWindow(ctypes.windll.kernel32.GetConsoleWindow(), 0)
        except Exception:
            pass
        # python.exe → pythonw.exe で再起動（恒久的にコンソールなし）
        exe = sys.executable
        if exe and os.path.basename(exe).lower() == "python.exe":
            pythonw = os.path.join(os.path.dirname(exe), "pythonw.exe")
            if os.path.exists(pythonw):
                import subprocess
                subprocess.Popen([pythonw] + sys.argv,
                                 creationflags=0x00000008)  # DETACHED_PROCESS
                sys.exit(0)

    # コマンドライン引数からパスを取得（画像の既定プログラムとして起動された場合）
    initial_path = sys.argv[1] if len(sys.argv) >= 2 else ""

    _set_windows_app_id()
    app = QApplication(sys.argv)
    app.setApplicationName(APP_NAME)
    app.setApplicationVersion(APP_VERSION)
    # AA_UseHighDpiPixmaps は Qt6 では不要・非推奨なので削除
    app.setStyleSheet(QSS)
    _app_icon = _build_app_icon()
    app.setWindowIcon(_app_icon)

    win = MainWindow(initial_path=initial_path)
    win.show()
    def _bring_to_front():
        try:
            was_maximized = win.isMaximized()
            if win.isMinimized():
                win.showNormal()
                if was_maximized:
                    win.showMaximized()
            win.raise_()
            win.activateWindow()
            if sys.platform == "win32":
                import ctypes
                hwnd = int(win.winId())
                if win.isMinimized():
                    ctypes.windll.user32.ShowWindow(hwnd, 9)  # SW_RESTORE
                elif win.isMaximized():
                    ctypes.windll.user32.ShowWindow(hwnd, 3)  # SW_MAXIMIZE
                else:
                    ctypes.windll.user32.ShowWindow(hwnd, 5)  # SW_SHOW
                ctypes.windll.user32.SetForegroundWindow(hwnd)
        except Exception:
            pass
    QTimer.singleShot(0, _bring_to_front)
    QTimer.singleShot(200, _bring_to_front)
    sys.exit(app.exec())


if __name__ == "__main__":
    main()
